73	  featureId: string;
74	  workspaceId: string;
75	  /** Executor invocation UUID. Passed as `HANDLE` env var; formalises existing docker usage. */
76	  handle: string;
77	  /** Git URL of the implementation repo (SSH or HTTPS). */
78	  taskRepoUrl: string;
79	  /** Feature branch the executor must check out and push to. */
80	  taskRepoBranch: string;
81	  /**
82	   * Branch that implementation PRs must target. Set by the orchestrator to the
83	   * feature branch (e.g. `feature/{featureId}`) so task PRs collect there before
84	   * the Handoff Trigger merges the feature branch into the repo's base branch.
85	   * Executors read this as `TASK_BASE_BRANCH` and pass it as the `base` field
86	   * when calling `pr-create`.
87	   */
88	  taskBaseBranch: string;
89	  /**
90	   * The impl repo's root base branch from workspace.yaml (e.g. `main`).
91	   * Used by the executor to create `feature/{featureId}` on the impl repo remote
92	   * when it does not yet exist. Distinct from `taskBaseBranch`, which is the PR
93	   * target (the feature branch itself) and must not be used as a push source.
94	   * Executors read this as `TASK_REPO_BASE_BRANCH`.
95	   */
96	  taskRepoBaseBranch?: string;
97	  /**
98	   * Per-handle base directory. The executor derives:
99	   *   - `${executorWorkdir}/impl` — implementation repo (replaces `taskRepoPath`)
100	   *   - `${executorWorkdir}/mgmt` — management repo clone (derives `WORKSPACE_ROOT`)
101	   */
102	  executorWorkdir: string;
103	  /** Git URL of the management (workspace) repo — cloned read-only by the executor. */
104	  mgmtRepoUrl: string;
105	  /** Path the executor must write result.json to. */
106	  resultPath: string;
107	  /** Optional token budget; absent for non-LLM executors. */
108	  budgetTokens?: number;
109	  /** Model ID to use for the LLM; resolved from workspace model_policy. */
110	  implementationModel?: string;
111	  sshPrivateKey: string;
112	  githubToken: string;
113	}
