115	export type TerminalStatus = "in_review" | "blocked" | "failed";
116	
117	export interface ExecutorResult {
118	  terminal_status: TerminalStatus;
119	  token_usage?: { input: number; output: number; model?: string };
120	  /** Required when terminal_status === "blocked". */
121	  blocked_reason?: string;
122	  /** Required when terminal_status === "blocked". */
123	  blocked_suggestion?: string;
124	  /**
125	   * URL of the implementation-repo pull request opened by the executor.
126	   * Populated whenever the executor opened a PR — independent of terminal_status.
127	   * A blocked task with a draft PR still reports pr_url so the failed attempt is
128	   * documented. Absent when no commits were pushed (no PR to open).
129	   */
130	  pr_url?: string;
131	  /**
132	   * @deprecated Populate executor_audit.cost_usd instead.
133	   * Retained for backward compatibility; the orchestrator no longer reads this field.
134	   */
135	  cost_usd?: number;
136	  /**
137	   * Path to a handover.md file written by the executor or the post-hoc recovery
138	   * routine (Layer 1). Optional — present only when a handover exists.
139	   * The orchestrator reads this on re-claim and prepends its contents to the next
140	   * agent's briefing under a "## Continuing previous run" heading (Layer 3).
141	   */
142	  handover_path?: string;
143	  /** Per-executor audit data (token usage, cost, MCP calls). Populated by the executor; absent when unavailable. */
144	  executor_audit?: ExecutorAudit;
145	}
146	
147	/** Terminal status values produced by the reviewer executor (kind=review). */
148	export type ReviewerTerminalStatus = "passed" | "change_requested" | "escalate";
149	
150	/** Per-run audit shape for the Claude executor. */
151	export interface ClaudeExecutorAudit {
152	  token_usage?: { input: number; output: number; model?: string };
153	  mcp_usage?: {
154	    rag_queries: Array<{ query: string; result_length: number }>;
155	    gitnexus_queries: Array<{
156	      tool: string;
157	      arguments: Record<string, unknown>;
158	      result_length: number;
159	    }>;
160	  };
161	}
162	
163	/** Per-run audit shape for the Hermes executor. token_usage is omitted unless Hermes exposes structured counts. */
164	export interface HermesExecutorAudit {
165	  turns?: number;
166	}
167	
168	/**
169	 * Namespaced executor audit data carried on result.json.
170	 * Each executor kind contributes its own sub-object so the orchestrator
171	 * can read cost regardless of which executor ran.
172	 */
173	export interface ExecutorAudit {
174	  /**
175	   * Executor-agnostic cost for final accounting. Intentionally at the ExecutorAudit
176	   * level (not inside a per-executor sub-object) so that cost can be aggregated
177	   * regardless of which executor ran — Claude, Hermes, or future types.
178	   * Per-executor audit sub-objects (claude, hermes) must NOT redeclare this field.
179	   */
180	  cost_usd?: number;
181	  claude?: ClaudeExecutorAudit;
182	  hermes?: HermesExecutorAudit;
183	}
184	
185	/**
186	 * Result written by the reviewer executor to result.json.
187	 * Routed to dispatchReviewResult in the reap loop — separate from ExecutorResult.
188	 */
189	export interface ReviewerResult {
190	  terminal_status: ReviewerTerminalStatus;
191	  verdict: ReviewerTerminalStatus;
192	  confidence: number;
193	  notes: string;
194	  review_url?: string;
195	  /** Set to true when the review POST was skipped due to HTTP 422 (self-review restriction). */
196	  self_review_skipped?: boolean;
197	  /** Per-executor audit data (token usage, cost, MCP calls). Populated by the executor; absent when unavailable. */
198	  executor_audit?: ExecutorAudit;
199	}
200	
201	/**
202	 * The orchestrator-side seam every executor must satisfy.
203	 * The default implementation is SubProcessAdapter; tests use FakeAdapter.
204	 */
205	export interface ExecutorAdapter {
206	  run(input: ExecutorInput): Promise<ExecutorResult>;
207	}
