export const DISPATCH_CONSUMER_GROUP = "dispatcher";

/**
 * Redis Stream key for the dispatch dead-letter queue (DLQ).
 * The dispatcher moves a job here after K failed redelivery attempts and
 * posts a synthetic `failed` completion to the broker `/callback` so the
 * orchestrator learns about the terminal failure through the normal path.
 */
export const DISPATCH_DLQ_KEY = "platform:dispatch:dlq";

/**
 * Credential-free payload the orchestrator XADDs to the dispatch stream.
 * The dispatcher reads this, injects credentials (GITHUB_TOKEN, SSH_PRIVATE_KEY),
 * and spawns the executor container.
 *
 * Secrets (GITHUB_TOKEN, SSH_PRIVATE_KEY) are NOT fields on this type.
 * The dispatcher is the sole credential holder; it injects them at spawn time.
 * Carrying secrets on the queue would re-privilege the orchestrator and expose
 * them to every consumer — both are design violations.
 */
export interface DispatchJob {
  /** Executor run identifier (UUID). Registered with the broker before enqueue. */
  handle: string;
  /** Single-use broker nonce; validated on /callback POST. */
  nonce: string;
  /** Discriminator: implementation run, review-fix, or rebase. */
  kind: "impl" | "review-fix" | "rebase";
  /** Task identifier (e.g. "T1"). */
  task_id: string;
  /** Feature identifier (e.g. "standalone-executor-hardening"). */
  feature_id: string;
  /** Workspace / tenant identifier. */
  workspace_id: string;
  /** Git URL of the implementation repo (SSH or HTTPS). */
  task_repo_url: string;
  /** Branch the executor must check out and push to. */
  task_repo_branch: string;
  /** Branch the executor must target when creating the implementation PR. */
  task_base_branch: string;
  /** Root base branch of the impl repo from workspace.yaml (e.g. "main"). */
  task_repo_base_branch: string;
  /** Git URL of the management (workspace) repo — cloned read-only by the executor. */
  mgmt_repo_url: string;
  /** Per-handle base directory inside the executor container (e.g. /workspace/exec-<handle>). */
  executor_workdir: string;
